import math
import sys

def solve_problem(input_str):
    lines = input_str.strip().split('\n')
    xp, yp, vp = map(int, lines[0].split())
    x, y, v, r = map(int, lines[1].split())

    R = math.sqrt(xp**2 + yp**2)

    # Persephone's initial angle
    theta0 = math.atan2(yp, xp)

    def persephone_pos(t):
        angle = theta0 + vp * t
        return (R * math.cos(angle), R * math.sin(angle))

    def can_reach(t):
        px, py = persephone_pos(t)
        dist = math.hypot(px - x, py - y)
        return dist <= v * t

    # Binary search for minimum time
    if can_reach(0):
        return "0.0000000000\n"

    low, high = 0.0, 1e9
    for _ in range(100):
        mid = (low + high) / 2
        if can_reach(mid):
            high = mid
        else:
            low = mid

    return f"{high:.10f}\n"

def solution(input_str):
    return solve_problem(input_str)

