                        count += 1

        # Check diamond squares
        # Size from 2 to min(n, m)
        for size in range(2, min(n, m) + 1):
            center_y = size // 2
            center_x = size // 2
            # Top of diamond is at (center_y - offset, center_x)
            # Bottom at (center_y + offset, center_x)
