        adj[u].append((v, c))
        adj[v].append((u, c))

    visited = [False] * (n + 1)
    assignments = [0] * (n + 1)
    num_components = 0
    consistent = True

    for i in range(1, n + 1):
        if not visited[i]:
            num_components += 1
            visited[i] = True
            assignments[i] = 0  # Arbitrarily assign to detect consistency
            queue = deque([i])

            while queue and consistent:
                u = queue.popleft()
                for v, c in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        if c == 1:  # Love: same partition
                            assignments[v] = assignments[u]
                        else:  # Hate: different partition
                            assignments[v] = 1 - assignments[u]
                        queue.append(v)
                    else:
                        # Check consistency with existing assignment
                        if c == 1:
                            if assignments[u] != assignments[v]:
                                consistent = False
                        else:
                            if assignments[u] == assignments[v]:
                                consistent = False
                        if not consistent:
                            break
                if not consistent:
                    break

    if not consistent:
        return '0'

    # With num_components connected components, there are 2^num_components 
    # valid assignments of x values, but flipping all assignments gives the 
    # same edge configuration, so divide by 2 = 2^(num_components - 1)
    result = pow(2, num_components - 1, MOD)
    return str(result)

