def check_geometric(arr):
    n = len(arr)

    # Any sequence with <= 2 elements is geometric
    if n <= 2:
        return True

    # All zeros is geometric
    if all(x == 0 for x in arr):
        return True

    # Find the first non-zero element
    first_non_zero_idx = -1
    for i in range(n):
        if arr[i] != 0:
            first_non_zero_idx = i
            break

    # If no non-zero element found, all zeros (already handled)
    if first_non_zero_idx == -1:
        return False

    # Find a consecutive pair of non-zero elements to compute ratio
    ratio_found = False
    ratio = 0.0
    for i in range(first_non_zero_idx, n - 1):
        if arr[i] != 0 and arr[i+1] != 0:
            ratio = arr[i+1] / arr[i]
            ratio_found = True
            break

    # If no consecutive non-zero pair is found after the first non-zero,
    # then all remaining elements must be 0 for it to be geometric
    if not ratio_found:
        for i in range(first_non_zero_idx + 1, n):
            if arr[i] != 0:
                return False
        return True

    # Verify the ratio throughout the sequence
    for i in range(n):
        if arr[i] == 0:
            # If current is 0, next must also be 0
            if i + 1 < n and arr[i+1] != 0:
                return False
        else:
            # If current is non-zero, next must be current * ratio
            if i + 1 < n:
                if arr[i+1] == 0:
                    return False
                # Use epsilon comparison for floating point
                if abs(arr[i+1] - arr[i] * ratio) > 1e-9:
                    return False

    return True

