    # Map values to positions in a
    val_to_pos = {}
    for i in range(n):
        val = a[i]
        if val not in val_to_pos:
            val_to_pos[val] = []
        val_to_pos[val].append(i)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(b_idx, last_pos):
        # Check if all elements of b are matched
        if b_idx == m:
            running_max = b[m-1]
            cost = 0
            for i in range(last_pos + 1, n):
                if a[i] > running_max:
                    cost += p[i]
                    running_max = a[i]
            return cost

        target = b[b_idx]
        result = INF

        if last_pos >= n - 1:
            return INF

        if target not in val_to_pos:
            return INF

        prev_max = b[b_idx - 1] if b_idx > 0 else -1

        # Try all valid positions for current b element
        for pos in val_to_pos[target]:
            if pos <= last_pos:
                continue

            # Cost to keep a[pos]
            cost = p[pos]

            # Cost to delete interfering elements between last_pos and pos
            interfering_cost = 0
            temp_max = prev_max

            for i in range(last_pos + 1, pos):
                if a[i] > temp_max:
                    interfering_cost += p[i]
                    temp_max = a[i]

            total = interfering_cost + cost
            total += dp(b_idx + 1, pos)
            result = min(result, total)

        return result

    ans = dp(0, -1)

    if ans >= INF:
        return "NO\n"

    return "YES\n" + str(ans)

