            adj[u].append(v)

    # BFS to compute shortest paths from a single source
    def get_distances(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    # Precompute all pairs shortest paths
    all_dist = [get_distances(i) for i in range(1, n + 1)]

    best_total = -1
    best_order = None

    # Try all valid 4-city sequences (to prevent O(n^4), use a clever approach)
    # Since we can revisit cities in intermediates, but must pick 4 distinct ones
    for start in range(1, n + 1):
        for second in range(1, n + 1):
            if second == start:
                continue
            d1 = all_dist[start][second]
            if d1 == -1:
                continue

            # Pre-filter reachable from second
            reachable_from_second = []
            for third in range(1, n + 1):
                if third == start or third == second:
                    continue
                d2 = all_dist[second][third]
                if d2 != -1:
                    reachable_from_second.append((third, d2))

            for third, d2 in reachable_from_second:
                # Pre-filter reachable from third
                reachable_from_third = []
                for fourth in range(1, n + 1):
                    if fourth == start or fourth == second or fourth == third:
                        continue
                    d3 = all_dist[third][fourth]
                    if d3 != -1:
                        reachable_from_third.append((fourth, d3))

                for fourth, d3 in reachable_from_third:
                    # Need to close the loop back to start
