                if num > 1:
                    if num not in prime_counts:
                        prime_counts[num] = [0] * n
                    prime_counts[num][i] += 1

            # Max flow with Dinic algorithm
            class Dinic:
                def __init__(self, n):
                    self.n = n
                    self.graph = [[] for _ in range(n)]
                    self.level = []

                def add_edge(self, u, v, capacity):
                    self.graph[u].append([v, len(self.graph[v]), capacity])
                    self.graph[v].append([u, len(self.graph[u]) - 1, 0])

                def bfs(self, s, t):
                    self.level = [-1] * self.n
                    self.level[s] = 0
                    queue = [s]
                    while queue:
                        u = queue.pop(0)
                        for v, rev, cap in self.graph[u]:
                            if cap > 0 and self.level[v] < 0:
                                self.level[v] = self.level[u] + 1
                                queue.append(v)
                    return self.level[t] >= 0

                def dfs(self, u, t, flow, ptr):
                    if u == t or flow == 0:
                        return flow
                    for i in range(ptr[u], len(self.graph[u])):
                        ptr[u] = i
                        v, rev, cap = self.graph[u][i]
                        if self.level[v] > self.level[u] and cap > 0:
                            pushed = self.dfs(v, t, min(flow, cap), ptr)
                            if pushed > 0:
                                self.graph[u][i][2] -= pushed
                                self.graph[v][rev][2] += pushed
                                return pushed
                    return 0

                def max_flow(self, s, t):
                    flow = 0
                    while self.bfs(s, t):
                        ptr = [0] * self.n
                        while True:
                            pushed = self.dfs(s, t, float('inf'), ptr)
                            if pushed == 0:
                                break
                            flow += pushed
                    return flow

            # Calculate answer
            ans = 0
            nodes = [0, 1, 2]  # source, positions, sink: 0=s, 1..n=positions, n+1=t

            for p, counts in prime_counts.items():
                # Build graph for this prime
                total_nodes = n + 2
                source, sink = 0, n + 1
                dinic = Dinic(total_nodes)

                # S -> i with capacity counts[i]
                for i in range(n):
                    if counts[i] > 0:
                        dinic.add_edge(source, 1 + i, counts[i])

                # i -> j with capacity infinity for each good pair
                INF = float('inf')
                for i, j in pairs:
                    dinic.add_edge(1 + i, 1 + j, INF)
                    dinic.add_edge(1 + j, 1 + i, INF)

                # j -> T with capacity counts[j]
                for j in range(n):
                    if counts[j] > 0:
                        dinic.add_edge(1 + j, sink, counts[j])

                flow = dinic.max_flow(source, sink)
                ans += flow // 2  # Each operation counted twice (once for each endpoint)

            return str(ans) + "\n"

        except Exception as e:
            return "0\n"

