def greedy_dom(n, m):
    """Find minimum dominating set greedily"""
    cells = list(range(n * m))
    covered = set()
    cover = []

    while len(covered) < n * m:
        best_cell = -1
        max_new = -1
        for c in cells:
            if c not in cover:
                new_covered = neighbors(c)
                new_count = len(new_covered - covered)
                if new_count > max_new:
                    max_new = new_count
                    best_cell = c

        if best_cell == -1:
            break
        cover.append(best_cell)
        covered.update(neighbor(best_cell))

    return len(cover)

def greedy_dom_with_start(n, m, start):
    """Greedy starting with initial covered cell"""
    cells = list(range(n * m))
