class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.MOD = 10**9 + 7

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        # expression ::= term | expression '+' term
        result = self.parse_term()

        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1  # skip '+'
            next_term = self.parse_term()
            result = concat(result, next_term)

        return result

    def parse_term(self):
        # term ::= number | number '-' number | number '(' expression ')'
        num = self.parse_number()

        if self.pos < len(self.s) and self.s[self.pos] == '-':
            self.pos += 1
            num2 = self.parse_number()
            # range: concatenate numbers from num to num2
            return calculate_range(num, num2)
        elif self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1  # skip '('
            expr = self.parse_expression()
            self.pos += 1  # skip ')'
            # repetition: concatenate expr, num times
            return calculate_repeat(num, expr)
        else:
            # just a number
            return number_to_int(num) % self.MOD

    def parse_number(self):
        start = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        return int(self.s[start:self.pos])


