    lines = input_str.strip().split('\n')
    n = int(lines[0])
    coords = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        coords.append((x, y))

    MOD = 1000000007

    # Check if triangle (i,k,j) is valid
    def is_triangle_valid(i, k, j):
        p, q, r = coords[i], coords[k], coords[j]

        # Signed area/orientation check
        def cross_product(a, b, c):
            return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

        # Check if point is on same side of all edges
        o1 = cross_product(p, q, r)
        o2 = cross_product(q, r, p)
        o3 = cross_product(r, p, q)

        return (o1 > 0 and o2 > 0 and o3 > 0) or (o1 < 0 and o2 < 0 and o3 < 0)

    # Check if diagonal (i,j) intersects any other polygon edge
    def is_diagonal_valid(i, j):
        for k in range(n):
            # Skip edges that share vertex with diagonal
            if k == i or k == j: continue
            nx = (k + 1) % n
            if nx == i or nx == j: continue

            def orientation(a, b, c):
                return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

            p1, q1, p2, q2 = coords[i], coords[j], coords[k], coords[nx]
            o1 = orientation(p1, q1, p2)
            o2 = orientation(p1, q1, q2)
            o3 = orientation(p2, q2, p1)
            o4 = orientation(p2, q2, q1)

            # Proper intersection check
            if (o1 * o2 < 0) and (o3 * o4 < 0):
                return False
            if o1 == 0 and min(p1[0], q1[0]) <= p2[0] <= max(p1[0], q1[0]) and min(p1[1], q1[1]) <= p2[1] <= max(p1[1], q1[1]):
                return False
            if o2 == 0 and min(p1[0], q1[0]) <= q2[0] <= max(p1[0], q1[0]) and min(p1[1], q1[1]) <= q2[1] <= max(p1[1], q1[1]):
                return False
            if o3 == 0 and min(p2[0], q2[0]) <= p1[0] <= max(p2[0], q2[0]) and min(p2[1], q2[1]) <= p1[1] <= max(p2[1], q2[1]):
                return False
            if o4 == 0 and min(p2[0], q2[0]) <= q1[0] <= max(p2[0], q2[0]) and min(p2[1], q2[1]) <= q1[1] <= max(p2[1], q2[1]):
                return False

        return True

    # DP: dp[i][j] = number of ways to triangulate subpolygon with vertices i to j
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][(i + 1) % n if i + 1 < n else 0] = 1

    # Build DP for increasing "length" between vertices
    for length in range(1, n - 1):
        for i in range(n - length):
            j = i + length + 1

            # Base case: consecutive vertices
            if length == 1:
                dp[i][j] = 1
                continue

            # Only proceed if diagonal is valid
            if not is_diagonal_valid(i, j):
                dp[i][j] = 0
                continue

            for k in range(i + 1, j):
                # Check if triangle is valid
                if is_triangle_valid(i, k, j):
                    # Both subproblems must be solvable
                    if dp[i][k] > 0 and dp[k][j] > 0:
                        dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    return str(dp[0][n - 1]) + '\n'

