def comb(n, k):
    """Compute binomial coefficient C(n, k)."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k

    result = 1
    i = 1
    while i <= k:
        result = result * (n - i + 1) // i
        i += 1
    return result

