    # Check if bipartite
    color = [-1] * n
    is_bipartite = True
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            stack = [start]
            while stack and is_bipartite:
                u = stack.pop()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        stack.append(v)
                    elif color[v] == color[u]:
                        is_bipartite = False
                        break

