    visited = [False] * n
    comp_count = 0
    for i in range(n):
        if not visited[i]:
            comp_count += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
