def count_independent_sets(n, adj):
    """Count independent sets using meet-in-the-middle"""
    mid = n // 2
    right_size = n - mid

    # Build right subgraph adjacency
    r_adj = [[False] * right_size for _ in range(right_size)]
    for u in range(mid, n):
        for v in adj[u]:
            if v >= mid:
                r_adj[u - mid][v - mid] = True

    # Precompute which subsets of right are independent
    r_indep = [False] * (1 << right_size)
    r_indep[0] = True
    for mask in range(1, 1 << right_size):
        ok = True
        for i in range(right_size):
            if not (mask & (1 << i)):
                continue
            for j in range(right_size):
                if r_adj[i][j] and (mask & (1 << j)):
                    ok = False
                    break
            if not ok:
                break
        r_indep[mask] = ok

    # SOS DP: for each mask, count independent sets that are subsets of it
    r_count = list(r_indep)
    for i in range(right_size):
        for mask in range(1 << right_size):
            if mask & (1 << i):
                r_count[mask] += r_count[mask ^ (1 << i)]

    # Build left subgraph adjacency and left-to-right edges
    l_to_r = [0] * mid
    for u in range(mid):
        for v in adj[u]:
            if v >= mid:
                l_to_r[u] |= (1 << (v - mid))

    # Check which subsets of left are independent
    l_indep = [False] * (1 << mid)
    l_indep[0] = True
    for mask in range(1, 1 << mid):
        ok = True
        for i in range(mid):
            if not (mask & (1 << i)):
                continue
            # Check neighbors in left
            for j in range(mid):
                if j != i and (mask & (1 << j)):
                    if i in adj[j]:  # j's adjacency in left
                        ok = False
                        break
            if not ok:
                break
        l_indep[mask] = ok

    # For each left independent set, add valid right sets
    ans = 0
    full_right_mask = (1 << right_size) - 1
    for mask in range(1 << mid):
        if l_indep[mask]:
            # Forbidden vertices in right
            forbidden = 0
            for i in range(mid):
                if mask & (1 << i):
                    forbidden |= l_to_r[i]

            # Valid rights are subsets of complement
            allow = full_right_mask ^ forbidden
            ans += r_count[allow]

    return ans
